    // src/components/AddFlower.js
import React, { useState } from "react";
import axios from "axios";
import { toast } from "react-toastify";
import "./AddFlower.css";

function AddFlower() {
    const [formData, setFormData] = useState({
        name: "",
        description: "",
        price: "",
        category: "",
        image: null,
    });

    // Handle input fields
    const handleChange = (e) => {
        if (e.target.name === "image") {
        setFormData({ ...formData, image: e.target.files[0] });
        } else {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        }
    };

    // Submit form
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
        let imageUrl = "";

        // 1. Upload image to Cloudinary (unsigned upload preset)
        if (formData.image) {
            const imageData = new FormData();
            imageData.append("file", formData.image);
            imageData.append("upload_preset", "flowers_Unsigned"); // 🔑 your unsigned preset
            imageData.append("cloud_name", "duq0nbvxs");           // 🔑 your cloud name

            const uploadRes = await axios.post(
            `https://api.cloudinary.com/v1_1/duq0nbvxs/image/upload`,
            imageData
            );

            imageUrl = uploadRes.data.secure_url;
        }

        // 2. Send flower data to backend (MongoDB)
        const res = await axios.post(
            "https://flower-delivery-website-af2b.onrender.com/api/flowers",
            {
            name: formData.name,
            description: formData.description,
            price: formData.price,
            category: formData.category,
            image: imageUrl, // ✅ stored as Cloudinary URL
            }
        );

        toast.success("Flower added successfully!");
        console.log("Saved flower:", res.data);

        // Reset form
        setFormData({
            name: "",
            description: "",
            price: "",
            category: "",
            image: null,
        });
        } catch (err) {
        console.error(err);
        toast.error("Failed to add flower.");
        }
    };

    return (
        <div className="add-flower">
        <h2>Add Flower</h2>
        <form onSubmit={handleSubmit} className="add-flower-form">
            <input
            type="text"
            name="name"
            placeholder="Flower Name"
            value={formData.name}
            onChange={handleChange}
            required
            />
            <textarea
            name="description"
            placeholder="Description"
            value={formData.description}
            onChange={handleChange}
            required
            />
            <input
            type="number"
            name="price"
            placeholder="Price"
            value={formData.price}
            onChange={handleChange}
            required
            />
            <input
            type="text"
            name="category"
            placeholder="Category"
            value={formData.category}
            onChange={handleChange}
            required
            />
            <input
            type="file"
            name="image"
            accept="image/*"
            onChange={handleChange}
            />

            <button type="submit">Add Flower</button>
        </form>
        </div>
    );
    }

export default AddFlower;
